// consent.go implements the consent chain entry canonical encoder and
// ML-DSA-65 signature verifier for the external Go verification SDK.
//
// # Cross-language byte-equality contract
//
// ConsentCanonical produces output that is byte-identical to
// internal/consent.ConsentCanonical for the same field values. This
// invariant is enforced by the golden vectors in
// sdk/testdata/consent_canonical_golden.json, which are generated by the
// internal encoder and verified by this package's test suite.
//
// # Canonical form (v2 — locked)
//
// Fields are serialised in STRICT ALPHABETICAL ORDER by canonical field
// name. The order is locked by TestConsentCanonical_FieldOrder_Alphabetical.
// Reordering is a breaking schema change.
//
// Encoding rules:
//   - String field: u32 big-endian byte-length (4 bytes) || raw UTF-8 bytes
//   - int64 field (ExpiresAtMs, TimestampMs): u64 big-endian (8 bytes)
//
// No separators, no field names, no JSON.
//
// # Ticket reference: pqc_05c-d4

package verification

import (
	"context"
	"crypto/sha512"
	"crypto/subtle"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"fmt"
	"unicode/utf8"

	mldsa65 "github.com/cloudflare/circl/sign/mldsa/mldsa65"
)

// consentEntryHashPrefix is the domain-separation prefix for consent chain
// entry SHA-512 hashes. MUST be byte-identical to the internal constant
// consentEntryHashPrefix in internal/consent/canonical.go.
//
// WARNING: This constant is part of the signed schema (v2). Changing it
// invalidates every previously-signed consent entry.
const consentEntryHashPrefix = "aleutian.consent.entry.v2:"

// ConsentTextHashPrefix is the domain-separation prefix for raw template
// SHA-512 hashes (HashTemplate). Exported for external callers who need
// to re-derive consent_template_hash. Mirrors internal/consent/canonical.go.
//
// WARNING: Part of the signed consent record format. Do NOT change without
// a versioned migration.
const ConsentTextHashPrefix = "aleutian.consent.text.v2:"

// ConsentRenderedHashPrefix is the domain-separation prefix for rendered
// consent text SHA-512 hashes (HashRendered). Mirrors the Go server constant
// consentRenderedHashPrefix in internal/consent/canonical.go.
//
// 18_20 review finding B4: split from ConsentTextHashPrefix so
// HashTemplate(b) != HashRendered(b) for any input b. Use this prefix
// when re-deriving consent_rendered_hash for GDPR Art. 7 verification.
//
// WARNING: Part of the GET /v1/consent/text response and POST
// /v1/consent/grant verification contract. Do NOT change without a
// versioned migration.
const ConsentRenderedHashPrefix = "aleutian.consent.rendered.v2:"

// maxConsentStringFieldBytes is the per-field byte length cap for canonical
// string fields. Mirrors internal/consent/canonical.go.
const maxConsentStringFieldBytes = 1024

// mldsa65SignatureSizeBytes is the exact byte length of an ML-DSA-65 signature
// per FIPS 204. Cloud KMS PQ_SIGN_ML_DSA_65 signatures are always exactly this
// size; a different length indicates a corrupt or truncated value.
const mldsa65SignatureSizeBytes = 3309

// ConsentEntryType is one of the four consent entry type strings.
// Values are identical to the storage.EntryType* constants and locked by
// the pqc_05c canonical form.
type ConsentEntryType string

const (
	// ConsentEntryTypeGranted represents a consent grant event.
	ConsentEntryTypeGranted ConsentEntryType = "consent_granted"

	// ConsentEntryTypeRevoked represents a consent revoke event.
	ConsentEntryTypeRevoked ConsentEntryType = "consent_revoked"

	// ConsentEntryTypeProcessingModeChange represents an operator-initiated
	// processing mode change event.
	ConsentEntryTypeProcessingModeChange ConsentEntryType = "processing_mode_change"

	// ConsentEntryTypeExpired represents a system-detected lapse: a
	// pii_inspection grant whose expires_at passed without an explicit
	// revoke. Written by the retention scanner (pqc_05g). Carries empty
	// actor and document fields and ProcessingModeAtWrite == "zk".
	ConsentEntryTypeExpired ConsentEntryType = "consent_expired"
)

// ErrInvalidConsentEntry is returned (wrapped with field context) when
// ConsentCanonical rejects a field value.
var ErrInvalidConsentEntry = errors.New("verification: invalid consent entry")

// ConsentChainEntry holds the 15 canonical fields of a consent chain entry.
//
// # Description
//
// Field names and types mirror internal/consent.ConsentChainEntry exactly.
// All string fields are raw UTF-8; no normalisation is applied. The field set
// is locked by pqc_05c-b's canonical form — adding, removing, or renaming any
// field is a breaking schema change.
//
// Field types use plain string and int64 (not named types) so callers can
// construct the struct directly from BQ row data without type conversions.
type ConsentChainEntry struct {
	ActorPseudonym           string
	ActorPseudonymKeyVersion string
	CompanyID                string
	ConsentID                string
	ConsentRenderedHash      string
	ConsentTemplateHash      string
	ConsentTextVersion       string
	// EntryType and EventType must be equal; both are included in the canonical
	// encoding for historical schema reasons. ConsentCanonical returns an error
	// if EntryType != EventType.
	EntryType                  ConsentEntryType
	EventType                  ConsentEntryType
	ExpiresAtMs                int64
	IdempotencyKeyHash         string
	ProcessingModeAtWrite      string
	ProcessingModeSetByEventID string
	SigningKeyID               string
	TimestampMs                int64
}

// ConsentCanonical serializes entry to the deterministic 15-field TLV byte
// sequence used as ML-DSA-65 signing input.
//
// # Description
//
// Validates the entry, then writes all 15 locked fields in alphabetical order
// using length-prefixed TLV encoding. Output is byte-identical to
// internal/consent.ConsentCanonical for the same field values.
//
// Encoding rules (identical to the internal encoder):
//   - String field: u32 big-endian byte-length (4 bytes) || raw UTF-8 bytes
//   - int64 field (ExpiresAtMs, TimestampMs): u64 big-endian, cast from int64
//
// # Inputs
//
//   - entry: the ConsentChainEntry to canonicalize; taken by value, never mutated
//
// # Outputs
//
//   - []byte: deterministic TLV bytes; non-nil on success
//   - error: ErrInvalidConsentEntry-wrapping error if any field fails validation
//
// # Limitations
//
//   - Returns an error if any required field is empty or any string exceeds 1 KiB
//
// # Assumptions
//
//   - All 15 canonical fields are populated; see field-by-field notes below
func ConsentCanonical(entry ConsentChainEntry) ([]byte, error) {
	if err := validateConsentCanonical(entry); err != nil {
		return nil, err
	}

	// Pre-size: 15 fields × ~50 bytes each ≈ 750 bytes typical
	buf := make([]byte, 0, 768)

	appendStr := func(s string) {
		var lenBuf [4]byte
		binary.BigEndian.PutUint32(lenBuf[:], uint32(len(s)))
		buf = append(buf, lenBuf[:]...)
		buf = append(buf, s...)
	}
	appendI64 := func(v int64) {
		var b [8]byte
		binary.BigEndian.PutUint64(b[:], uint64(v))
		buf = append(buf, b[:]...)
	}

	// Locked alphabetical field order — 15 fields.
	// DO NOT reorder. Order is part of the signed schema (v2).

	// 1. actor_pseudonym
	appendStr(entry.ActorPseudonym)
	// 2. actor_pseudonym_key_version
	appendStr(entry.ActorPseudonymKeyVersion)
	// 3. company_id
	appendStr(entry.CompanyID)
	// 4. consent_id
	appendStr(entry.ConsentID)
	// 5. consent_rendered_hash (empty string allowed for processing_mode_change)
	appendStr(entry.ConsentRenderedHash)
	// 6. consent_template_hash (empty string allowed for processing_mode_change)
	appendStr(entry.ConsentTemplateHash)
	// 7. consent_text_version (empty string allowed for processing_mode_change)
	appendStr(entry.ConsentTextVersion)
	// 8. entry_type
	appendStr(string(entry.EntryType))
	// 9. event_type (intentional duplicate of entry_type per locked field order row 9)
	appendStr(string(entry.EventType))
	// 10. expires_at_ms — encoded as u64 big-endian; 0 is the no-expiry sentinel
	appendI64(entry.ExpiresAtMs)
	// 11. idempotency_key_hash
	appendStr(entry.IdempotencyKeyHash)
	// 12. processing_mode_at_write
	appendStr(entry.ProcessingModeAtWrite)
	// 13. processing_mode_set_by_event_id
	appendStr(entry.ProcessingModeSetByEventID)
	// 14. signing_key_id
	appendStr(entry.SigningKeyID)
	// 15. timestamp_ms — encoded as u64 big-endian
	appendI64(entry.TimestampMs)

	return buf, nil
}

// DeriveConsentContentHash computes hex(SHA-512("aleutian.consent.entry.v2:" || canonical)).
//
// # Description
//
// Implements the same formula as internal/consent.DeriveConsentContentHash.
// The result is the 128-character hex string stored as content_hash in the
// audit_entries BQ row.
//
// # Inputs
//
//   - canonical: the TLV bytes returned by ConsentCanonical for the entry
//
// # Outputs
//
//   - string: 128 lowercase hex characters (SHA-512 output)
//
// # Assumptions
//
//   - canonical was produced by ConsentCanonical for the same entry
func DeriveConsentContentHash(canonical []byte) string {
	h := sha512.New()
	h.Write([]byte(consentEntryHashPrefix))
	h.Write(canonical)
	return hex.EncodeToString(h.Sum(nil))
}

// VerifyConsentEntry verifies the ML-DSA-65 signature and content hash for a
// consent chain entry.
//
// # Description
//
// Performs the same 4-step verification as internal/chainlinker.verifyConsentEntry,
// minus the cross-tenant check (which is the caller's responsibility):
//
//  1. Re-derive canonical bytes via ConsentCanonical.
//  2. Re-derive content_hash via DeriveConsentContentHash.
//  3. Constant-time compare against storedContentHash.
//  4. Verify ML-DSA-65 signature via GetPublicKey + circl.
//
// # Inputs
//
//   - ctx: context (reserved; not currently used for I/O)
//   - entry: the ConsentChainEntry as stored; must produce identical canonical bytes
//     to those that were signed
//   - storedContentHash: the 128-char hex content_hash from the audit_entries row
//   - sigBytes: the raw ML-DSA-65 signature bytes (exactly 3309 bytes)
//   - keyID: the signing key ID from the consent_chain_entries row
//
// # Outputs
//
//   - error: nil on success; ErrInvalidSignature on any cryptographic mismatch;
//     ErrInvalidConsentEntry if canonical re-derivation fails
//
// # Cross-tenant check is the caller's responsibility
//
// This function verifies cryptographic integrity only. The caller MUST check
// entry.CompanyID == owningChainCompanyID before calling:
//
//	if entry.CompanyID != owningChainCompanyID {
//	    return CrossTenantReplayError(...)
//	}
//	if err := VerifyConsentEntry(ctx, entry, storedContentHash, sigBytes, keyID); err != nil {
//	    return fmt.Errorf("consent verify: %w", err)
//	}
//
// # Assumptions
//
//   - sigBytes is exactly 3309 bytes (ML-DSA-65 signature size per FIPS 204)
//   - keyID is present in the embedded key set
func VerifyConsentEntry(
	ctx context.Context,
	entry ConsentChainEntry,
	storedContentHash string,
	sigBytes []byte,
	keyID string,
) error {
	// Step 1: re-derive canonical bytes
	canonical, err := ConsentCanonical(entry)
	if err != nil {
		return fmt.Errorf("VerifyConsentEntry: canonicalize: %w", err)
	}

	// Step 2: re-derive content_hash
	expectedHash := DeriveConsentContentHash(canonical)

	// Step 3: constant-time compare content_hash.
	// INVARIANT: content hash check MUST precede key lookup (Step 4).
	// Rationale: checking the hash first means an attacker who controls keyID
	// cannot use a timing difference on the GetPublicKey call to learn whether
	// the stored content hash is valid. Reordering Steps 3 and 4 would create
	// a key-ID oracle.
	if subtle.ConstantTimeCompare([]byte(expectedHash), []byte(storedContentHash)) != 1 {
		return fmt.Errorf("%w: content hash mismatch", ErrInvalidSignature)
	}

	// Step 4: ML-DSA-65 signature verify (only reached when content hash passes).
	rawKey, err := GetPublicKey(keyID)
	if err != nil {
		return fmt.Errorf("VerifyConsentEntry: get public key: %w", err)
	}

	// RS-3: Validate signature length before passing to the crypto library.
	if len(sigBytes) != mldsa65SignatureSizeBytes {
		return fmt.Errorf("%w: invalid signature length %d (want %d)", ErrInvalidSignature, len(sigBytes), mldsa65SignatureSizeBytes)
	}

	scheme := mldsa65.Scheme()
	pub, err := scheme.UnmarshalBinaryPublicKey(rawKey)
	if err != nil {
		// Do not surface the internal parse error: it may contain key material details.
		return fmt.Errorf("%w: public key parse failed", ErrInvalidSignature)
	}

	// nil opts = empty context string = FIPS 204 §5.3 pure ML-DSA.Verify (not HashML-DSA).
	// Cloud KMS PQ_SIGN_ML_DSA_65 uses the same pure variant with no context string.
	if !scheme.Verify(pub, canonical, sigBytes, nil) {
		return fmt.Errorf("%w: ML-DSA-65 signature invalid", ErrInvalidSignature)
	}

	return nil
}

// validateConsentCanonical validates entry fields before canonical serialization.
//
// # Description
//
// Mirrors the validation logic in internal/consent.validateForCanonical.
// Validates required fields, size caps, UTF-8 validity, control byte
// rejection, processing mode, and timestamp constraints.
func validateConsentCanonical(e ConsentChainEntry) error {
	// Required string fields (all entry types).
	type strField struct {
		name  string
		value string
	}
	required := []strField{
		{"company_id", e.CompanyID},
		{"consent_id", e.ConsentID},
		{"entry_type", string(e.EntryType)},
		{"event_type", string(e.EventType)},
		{"idempotency_key_hash", e.IdempotencyKeyHash},
		{"processing_mode_at_write", e.ProcessingModeAtWrite},
		{"signing_key_id", e.SigningKeyID},
	}
	// actor_pseudonym + actor_pseudonym_key_version: required for entries
	// that represent a human action. consent_expired (pqc_05g) is system-
	// generated by the retention scanner and carries empty actor fields.
	if e.EntryType != ConsentEntryTypeExpired {
		required = append(required,
			strField{"actor_pseudonym", e.ActorPseudonym},
			strField{"actor_pseudonym_key_version", e.ActorPseudonymKeyVersion},
		)
	}
	// consent_rendered_hash, consent_template_hash, consent_text_version are
	// required for grant only. revoke, processing_mode_change, and
	// consent_expired all carry empty hash/version fields.
	if e.EntryType == ConsentEntryTypeGranted {
		required = append(required,
			strField{"consent_rendered_hash", e.ConsentRenderedHash},
			strField{"consent_template_hash", e.ConsentTemplateHash},
			strField{"consent_text_version", e.ConsentTextVersion},
		)
	}
	for _, f := range required {
		if f.value == "" {
			return fmt.Errorf("%w: %s is empty", ErrInvalidConsentEntry, f.name)
		}
		if len(f.value) > maxConsentStringFieldBytes {
			return fmt.Errorf("%w: %s exceeds %d bytes", ErrInvalidConsentEntry, f.name, maxConsentStringFieldBytes)
		}
		if !utf8.ValidString(f.value) {
			return fmt.Errorf("%w: %s is not valid UTF-8", ErrInvalidConsentEntry, f.name)
		}
		if hasConsentDisallowedControlBytes(f.value) {
			return fmt.Errorf("%w: %s contains a disallowed control byte", ErrInvalidConsentEntry, f.name)
		}
	}

	// consent_expired entries: enforce empty document/actor fields. Mirrors
	// the server-side validateForCanonical guard so cross-language verifiers
	// reject any entry mis-built with stray bytes in those slots.
	if e.EntryType == ConsentEntryTypeExpired {
		empties := []strField{
			{"actor_pseudonym", e.ActorPseudonym},
			{"actor_pseudonym_key_version", e.ActorPseudonymKeyVersion},
			{"consent_rendered_hash", e.ConsentRenderedHash},
			{"consent_template_hash", e.ConsentTemplateHash},
			{"consent_text_version", e.ConsentTextVersion},
		}
		for _, f := range empties {
			if f.value != "" {
				return fmt.Errorf("%w: %s must be empty for consent_expired entries", ErrInvalidConsentEntry, f.name)
			}
		}
	}

	// Optional: processing_mode_set_by_event_id
	pmSetBy := e.ProcessingModeSetByEventID
	if len(pmSetBy) > maxConsentStringFieldBytes {
		return fmt.Errorf("%w: processing_mode_set_by_event_id exceeds %d bytes",
			ErrInvalidConsentEntry, maxConsentStringFieldBytes)
	}
	if pmSetBy != "" {
		if !utf8.ValidString(pmSetBy) {
			return fmt.Errorf("%w: processing_mode_set_by_event_id is not valid UTF-8", ErrInvalidConsentEntry)
		}
		if hasConsentDisallowedControlBytes(pmSetBy) {
			return fmt.Errorf("%w: processing_mode_set_by_event_id contains a disallowed control byte", ErrInvalidConsentEntry)
		}
	}

	// Processing mode
	switch e.ProcessingModeAtWrite {
	case "pii_inspection", "zk":
		// valid
	default:
		return fmt.Errorf("%w: processing_mode_at_write is not a known mode", ErrInvalidConsentEntry)
	}
	if e.ProcessingModeAtWrite == "pii_inspection" && e.ProcessingModeSetByEventID == "" {
		return fmt.Errorf("%w: processing_mode_set_by_event_id must be non-empty when processing_mode_at_write is pii_inspection",
			ErrInvalidConsentEntry)
	}

	// Entry type validity
	if !isValidConsentEntryType(e.EntryType) {
		return fmt.Errorf("%w: entry_type is not a known ConsentEntryType", ErrInvalidConsentEntry)
	}
	if !isValidConsentEntryType(e.EventType) {
		return fmt.Errorf("%w: event_type is not a known ConsentEntryType", ErrInvalidConsentEntry)
	}
	if e.EntryType != e.EventType {
		return fmt.Errorf("%w: entry_type != event_type", ErrInvalidConsentEntry)
	}

	// Timestamps
	if e.TimestampMs <= 0 {
		return fmt.Errorf("%w: timestamp_ms must be > 0", ErrInvalidConsentEntry)
	}
	if e.ExpiresAtMs < 0 {
		return fmt.Errorf("%w: expires_at_ms must be >= 0", ErrInvalidConsentEntry)
	}

	// Per-entry-type semantic constraints
	switch e.EntryType {
	case ConsentEntryTypeRevoked:
		if e.ExpiresAtMs != 0 {
			return fmt.Errorf("%w: consent_revoked entry must have expires_at_ms == 0", ErrInvalidConsentEntry)
		}
	case ConsentEntryTypeGranted:
		if e.ExpiresAtMs != 0 && e.ExpiresAtMs <= e.TimestampMs {
			return fmt.Errorf("%w: consent_granted expires_at_ms must be > timestamp_ms (or 0 for no expiry)",
				ErrInvalidConsentEntry)
		}
	case ConsentEntryTypeProcessingModeChange:
		// No additional constraints.
	case ConsentEntryTypeExpired:
		if e.ExpiresAtMs == 0 {
			return fmt.Errorf("%w: consent_expired entry requires expires_at_ms != 0", ErrInvalidConsentEntry)
		}
		if e.ProcessingModeAtWrite != "zk" {
			return fmt.Errorf("%w: consent_expired entry requires processing_mode_at_write == zk", ErrInvalidConsentEntry)
		}
		if e.ProcessingModeSetByEventID != "" {
			return fmt.Errorf("%w: consent_expired entry must have empty processing_mode_set_by_event_id", ErrInvalidConsentEntry)
		}
	}

	return nil
}

// isValidConsentEntryType returns true for the four known entry types.
func isValidConsentEntryType(t ConsentEntryType) bool {
	switch t {
	case ConsentEntryTypeGranted, ConsentEntryTypeRevoked,
		ConsentEntryTypeProcessingModeChange, ConsentEntryTypeExpired:
		return true
	default:
		return false
	}
}

// hasConsentDisallowedControlBytes mirrors the internal/consent implementation.
// Rejects C0 control bytes except HT (0x09), LF (0x0A), CR (0x0D).
//
// NOTE: 0x7F (DEL) is intentionally NOT rejected here to maintain byte-identical
// behaviour with internal/consent.hasDisallowedControlBytes. Adding 0x7F rejection
// to the SDK while the internal encoder does not reject it would cause SDK
// verification to fail for any entry whose fields contain DEL bytes (however
// unlikely). If 0x7F rejection is desired, it must be added to the internal
// encoder first and this function updated in the same commit.
func hasConsentDisallowedControlBytes(s string) bool {
	for i := 0; i < len(s); i++ {
		b := s[i]
		if b < 0x20 && b != 0x09 && b != 0x0A && b != 0x0D {
			return true
		}
	}
	return false
}
